import{_ as o,o as t,c as i,a5 as n}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Changelog: v2.6","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.6.md","filePath":"sections/changelog/v2.6.md"}'),a={name:"sections/changelog/v2.6.md"};function d(l,e,r,s,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog-v2-6" tabindex="-1">Changelog: v2.6 <a class="header-anchor" href="#changelog-v2-6" aria-label="Permalink to &quot;Changelog: v2.6&quot;">​</a></h1><h2 id="v2-6-1-2026-09-13" tabindex="-1">v2.6.1 (2026-09-13) <a class="header-anchor" href="#v2-6-1-2026-09-13" aria-label="Permalink to &quot;v2.6.1 (2026-09-13)&quot;">​</a></h2><ul><li>TCP viewer: restored panes auto-reconnect (<code>--no-auto-connect</code> / <code>RAYRAI_TCP_VIEWER_AUTO_CONNECT=0</code>); command-line endpoint applies to the first pane only.</li><li>TCP viewer: pane outlines/dividers drawn under popups.</li><li>Windows installer verifies all CMake package files are staged.</li></ul><h2 id="v2-6-0-2026-09-12" tabindex="-1">v2.6.0 (2026-09-12) <a class="header-anchor" href="#v2-6-0-2026-09-12" aria-label="Permalink to &quot;v2.6.0 (2026-09-12)&quot;">​</a></h2><p><strong>Tendons</strong></p><ul><li><code>World::addSpatialTendon</code>, <code>addFixedTendon</code>, <code>addTendonCoupling</code> and get/remove functions; <code>raisim::Tendon</code>. See <a href="./../Tendons.html">Tendons</a>.</li><li>Spatial tendons through sites and anchors, wrapping spheres/cylinders, side sites, pulley branches; fixed tendons over joint coordinates.</li><li>Springs, deadband, friction loss, armature, length limits; <code>Tendon::Drive</code> actuation, <code>setTension</code>, <code>setActuationForce</code>; polynomial <code>TendonCoupling</code>.</li><li>Attach to articulated systems, rigid bodies, world anchors, deformable and granular particles; solved with contacts (no cost without tendons).</li><li>Wires (<code>addStiffWire</code>, <code>addCompliantWire</code>, <code>addCustomWire</code>) are now tendon wrappers: implicit springs, no longer reported as contacts, width 0 hides them.</li><li>MJCF <code>&lt;tendon&gt;</code> (spatial/fixed) and <code>&lt;equality&gt;&lt;tendon&gt;</code> import.</li></ul><p><strong>World</strong></p><ul><li><code>World::captureCheckpoint</code> / <code>restoreCheckpoint</code> for in-memory rewind.</li><li>World XML export/import covers simulation settings, all material properties, per-object tuning, mesh collision/CoACD options, articulated control state, sensors, deformable/granular objects and tendons; full-precision, locale-independent numbers.</li><li>Sleeping: default <code>quietSteps</code> 2 → 5, both thresholds must hold, tendon-linked bodies sleep together.</li><li><code>setStaticFrictionVelocityThreshold</code> treats ≤0 as disabled; IMU noise defaults to none.</li><li>Contact solver cache-line layout (granular scenes 3–8% faster); repeated object removal is ASan-clean.</li></ul><p><strong>RaisimServer</strong></p><ul><li><code>launchServer</code> binds before returning (correct <code>getPort</code>); tendons streamed; viewer can delete tendons.</li></ul><p><strong>rayrai</strong></p><ul><li>Tendons drawn automatically (<code>getTendonVisual</code>).</li><li>Faster PBR: instanced unshadowed primitives (1,024 boxes 8.2 → 0.56 ms), specialized depth prepasses (+14.5% on dense meshes).</li><li>Lazy camera targets and depth-only allocation (−69.5% VRAM for depth, −33% for RGB over 8 contexts); checker texture leak fixed.</li><li>Displaced heightmap normals; <code>setKeyboardInputEnabled</code>; fixed missing robot meshes under PBR and heightmap texture-unit clash.</li></ul><p><strong>TCP viewer</strong></p><ul><li>Simulate a dropped world XML or <code>--simulate world.xml</code> in a child process.</li><li>Scene editing (spawn, delete, export XML), Ctrl-drag interaction wire, Live Signals with CSV export, MP4/PNG recording.</li><li>File browser, camera presets, grouped object list, help panel, more render options.</li><li>Split panes (<code>Ctrl+Shift+O/E/W</code>) with a server discovery table; layout saved in <code>~/.rayrai/settings.yaml</code>.</li><li><code>SimControlRequest</code> renamed to <code>ClientRequest</code>.</li></ul>',14)])])}const g=o(a,[["render",d]]);export{u as __pageData,g as default};
